/**
 * MCP tool: create_tokens_from_css
 * Parses CSS custom properties and creates Figma Variables via batch createToken calls.
 * Optionally creates a visual swatch board for color tokens.
 */
import { figmaWebSocket } from '../websocket.js';
export const createTokensFromCssSchema = {
    name: 'create_tokens_from_css',
    description: 'Parse CSS custom properties (--var-name: value) and create Figma Variables (design tokens). ' +
        'Supports colors (hex, rgb, hsl), numbers (px, rem), and strings. ' +
        'Resolves var() references within the CSS. Optionally creates a visual color swatch board.',
    inputSchema: {
        type: 'object',
        properties: {
            css: {
                type: 'string',
                description: 'CSS text containing custom properties (e.g. ":root { --color-primary: #0066FF; }")',
            },
            collection: {
                type: 'string',
                description: 'Figma variable collection name (default: "Design Tokens")',
            },
            createSwatches: {
                type: 'boolean',
                description: 'Create a visual color swatch board in Figma for color tokens (default: false)',
            },
            prefix: {
                type: 'string',
                description: 'Only import variables matching this prefix (e.g. "--color-" to only get color vars)',
            },
        },
        required: ['css'],
    },
};
function isHexColor(value) {
    return /^#([0-9a-fA-F]{3,4}|[0-9a-fA-F]{6}|[0-9a-fA-F]{8})$/.test(value.trim());
}
function isRgbColor(value) {
    return /^rgba?\s*\(/.test(value.trim());
}
function isHslColor(value) {
    return /^hsla?\s*\(/.test(value.trim());
}
function isColor(value) {
    const v = value.trim();
    return isHexColor(v) || isRgbColor(v) || isHslColor(v);
}
function isNumericValue(value) {
    const v = value.trim();
    return /^-?[\d.]+(%|px|rem|em|vh|vw|deg|s|ms)?$/.test(v);
}
function parseNumericValue(value) {
    return parseFloat(value.trim());
}
function hslToHex(h, s, l) {
    s /= 100;
    l /= 100;
    const a = s * Math.min(l, 1 - l);
    const f = (n) => {
        const k = (n + h / 30) % 12;
        const color = l - a * Math.max(Math.min(k - 3, 9 - k, 1), -1);
        return Math.round(255 * color).toString(16).padStart(2, '0');
    };
    return `#${f(0)}${f(8)}${f(4)}`;
}
function resolveHslToHex(value) {
    const match = value.match(/hsla?\s*\(\s*([\d.]+)\s*,?\s*([\d.]+)%?\s*,?\s*([\d.]+)%?/);
    if (!match)
        return value;
    return hslToHex(parseFloat(match[1]), parseFloat(match[2]), parseFloat(match[3]));
}
/**
 * Parse CSS text for custom properties.
 */
function parseCssCustomProperties(css, prefix) {
    const tokens = new Map();
    // First pass: extract all --var: value pairs
    const rawValues = new Map();
    const varRegex = /--([\w-]+)\s*:\s*([^;]+)/g;
    let match;
    while ((match = varRegex.exec(css)) !== null) {
        const name = match[1];
        const value = match[2].trim();
        if (prefix && !`--${name}`.startsWith(prefix))
            continue;
        rawValues.set(name, value);
    }
    // Second pass: resolve var() references
    function resolveValue(value, depth = 0) {
        if (depth > 10)
            return value;
        return value.replace(/var\(\s*--([\w-]+)(?:\s*,\s*([^)]+))?\s*\)/g, (_m, refName, fallback) => {
            const resolved = rawValues.get(refName);
            if (resolved !== undefined) {
                return resolveValue(resolved, depth + 1);
            }
            return fallback?.trim() || `var(--${refName})`;
        });
    }
    // Third pass: classify types
    for (const [name, rawValue] of rawValues) {
        const resolvedValue = resolveValue(rawValue);
        let type;
        let numericValue;
        let finalValue = resolvedValue;
        if (isHslColor(resolvedValue)) {
            finalValue = resolveHslToHex(resolvedValue);
            type = 'COLOR';
        }
        else if (isColor(resolvedValue)) {
            type = 'COLOR';
        }
        else if (isNumericValue(resolvedValue)) {
            type = 'NUMBER';
            numericValue = parseNumericValue(resolvedValue);
        }
        else {
            type = 'STRING';
        }
        tokens.set(name, {
            name,
            rawValue,
            resolvedValue: finalValue,
            type,
            numericValue,
        });
    }
    return tokens;
}
/**
 * Execute the CSS → Figma Variables tool.
 */
export async function createTokensFromCss(args) {
    const css = args.css;
    if (!css)
        throw new Error('Missing required parameter: css');
    const collection = args.collection || 'Design Tokens';
    const createSwatches = args.createSwatches || false;
    const prefix = args.prefix;
    const tokens = parseCssCustomProperties(css, prefix);
    if (tokens.size === 0) {
        return {
            success: true,
            message: 'No CSS custom properties found' + (prefix ? ` matching prefix "${prefix}"` : ''),
            created: 0,
        };
    }
    // Build batch operations for createToken
    const tokenOps = [];
    const tokenList = [];
    for (const [, token] of tokens) {
        const value = token.type === 'NUMBER' ? (token.numericValue ?? 0) : token.resolvedValue;
        tokenOps.push({
            command: 'createToken',
            params: {
                collection,
                name: token.name,
                type: token.type,
                value,
            },
        });
        tokenList.push({ name: token.name, type: token.type, value });
    }
    // Execute in batches of 200 (plugin limit)
    const allResults = [];
    for (let i = 0; i < tokenOps.length; i += 200) {
        const chunk = tokenOps.slice(i, i + 200);
        const batchResult = await figmaWebSocket.sendCommand('batch', {
            operations: chunk,
            continueOnError: true,
        });
        allResults.push(...batchResult.results);
    }
    const created = allResults.filter(r => r.success).length;
    const failed = allResults.filter(r => !r.success);
    let swatchBoardId;
    if (createSwatches) {
        const colorTokens = tokenList.filter(t => t.type === 'COLOR');
        if (colorTokens.length > 0) {
            swatchBoardId = await createSwatchBoard(colorTokens, collection);
        }
    }
    return {
        success: true,
        collection,
        created,
        total: tokens.size,
        failed: failed.length > 0 ? failed.map((f) => ({
            token: tokenList[allResults.indexOf(f)]?.name,
            error: f.error,
        })) : [],
        tokens: tokenList,
        swatchBoardId,
    };
}
/**
 * Create a visual swatch board showing color tokens.
 */
async function createSwatchBoard(colorTokens, collectionName) {
    const SWATCH_SIZE = 64;
    const GAP = 8;
    const COLS = 8;
    const PADDING = 24;
    const LABEL_HEIGHT = 20;
    const rows = Math.ceil(colorTokens.length / COLS);
    const boardWidth = PADDING * 2 + COLS * SWATCH_SIZE + (COLS - 1) * GAP;
    const boardHeight = PADDING * 2 + 40 + rows * (SWATCH_SIZE + LABEL_HEIGHT + GAP);
    const ops = [];
    // Op 0: Board frame
    ops.push({
        command: 'createFrame',
        params: {
            name: `${collectionName} — Color Swatches`,
            width: boardWidth,
            height: boardHeight,
            fillColor: '#FFFFFF',
            cornerRadius: 12,
        },
    });
    // Op 1: Title text
    ops.push({
        command: 'createText',
        params: {
            text: `${collectionName} — ${colorTokens.length} Colors`,
            fontSize: 18,
            fontWeight: 'Bold',
            fillColor: '#000000',
            parentId: '$0.id',
            x: PADDING,
            y: PADDING,
        },
    });
    // Swatch rects + labels
    for (let i = 0; i < colorTokens.length; i++) {
        const col = i % COLS;
        const row = Math.floor(i / COLS);
        const x = PADDING + col * (SWATCH_SIZE + GAP);
        const y = PADDING + 40 + row * (SWATCH_SIZE + LABEL_HEIGHT + GAP);
        ops.push({
            command: 'createRectangle',
            params: {
                name: colorTokens[i].name,
                width: SWATCH_SIZE,
                height: SWATCH_SIZE,
                fillColor: String(colorTokens[i].value),
                cornerRadius: 8,
                parentId: '$0.id',
                x,
                y,
            },
        });
        const label = colorTokens[i].name.length > 12
            ? colorTokens[i].name.slice(0, 11) + '\u2026'
            : colorTokens[i].name;
        ops.push({
            command: 'createText',
            params: {
                text: label,
                fontSize: 9,
                fillColor: '#666666',
                parentId: '$0.id',
                x: x + 2,
                y: y + SWATCH_SIZE + 2,
            },
        });
    }
    // Send in chunks of 200
    let boardId = '';
    for (let i = 0; i < ops.length; i += 200) {
        const chunk = ops.slice(i, i + 200);
        const result = await figmaWebSocket.sendCommand('batch', {
            operations: chunk,
            continueOnError: true,
        });
        if (i === 0 && result.results[0]?.success) {
            boardId = result.results[0].result?.id || '';
        }
    }
    return boardId;
}
